attributes.cssVariables:
:root {
  --background: #f7f5ee;
  --foreground: #22301f;
  --card: #fffdf7;
  --card-foreground: #22301f;
  --popover: #fffdf7;
  --popover-foreground: #22301f;
  --primary: #1f6f54;
  --primary-foreground: #f4faf6;
  --secondary: #ecefe3;
  --secondary-foreground: #22301f;
  --muted: #edeadf;
  --muted-foreground: #71765f;
  --accent: #e4ead9;
  --accent-foreground: #22301f;
  --border: #ddd8c4;
  --input: #ddd8c4;
  --ring: #1f6f54;
  --radius: 0.375rem;
  --font-sans: 'IBM Plex Sans', system-ui, sans-serif;
  --font-serif: 'Fraunces', Georgia, serif;
  --font-heading: 'Fraunces', Georgia, serif;
  --font-mono: 'IBM Plex Mono', ui-monospace, monospace;
  --shadow-xs: 0 1px 2px rgba(34, 48, 31, 0.06);
  --shadow-md: 0 4px 16px rgba(34, 48, 31, 0.1);
}

h1,
h2,
h3 {
  font-family: var(--font-serif);
  letter-spacing: -0.01em;
}
